import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";import"./chunks/assets.DDNpi1qx.js";var i=JSON.parse(`{"title":"Wait & Act","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/field-types/wait-act.md","filePath":"documentation/field-types/wait-act.md","lastUpdated":1792256923000}`),a={name:`documentation/field-types/wait-act.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="wait-act" tabindex="-1">Wait &amp; Act <a class="header-anchor" href="#wait-act" aria-label="Permalink to “Wait &amp; Act”">​</a></h1><p>The <strong>Wait &amp; Act</strong> field type allows you to monitor an element on a webpage until a specified condition is satisfied (such as the element becoming visible or invisible) and then execute an action, such as clicking the monitored element or clicking another element on the page.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>In modern web applications, elements like modal overlays, confirmation dialogs, notifications, or dynamically rendered buttons frequently change state. The Wait &amp; Act field type automates waiting and responding to these dynamic states in the background:</p><ul><li><strong>Condition Monitoring</strong> - Continuously poll the DOM until the monitored element becomes visible or invisible.</li><li><strong>Configurable Polling &amp; Timeout</strong> - Customize the polling interval and optionally specify a maximum timeout before aborting.</li><li><strong>Action on Success</strong> - Automatically trigger an action when the condition is met (click the monitored element or click another element).</li><li><strong>Wait Before Action</strong> - Optionally introduce a delay after the condition is met before executing the action.</li></ul><div class="info custom-block"><p class="custom-block-title">Background Execution</p><p>The <strong>Wait &amp; Act</strong> field operates asynchronously in the background. Once the polling process starts, it immediately returns so that subsequent form fields and actions can continue executing without being blocked while this field monitors its condition.</p></div><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><h3 id="condition" tabindex="-1">Condition <a class="header-anchor" href="#condition" aria-label="Permalink to “Condition”">​</a></h3><p>Select the state condition to wait for:</p><ul><li><strong>Element becomes visible</strong> - Waits until the monitored element exists and is visible in the DOM.</li><li><strong>Element becomes invisible</strong> - Waits until the monitored element disappears or is removed from the DOM.</li></ul><h3 id="poll-interval-ms" tabindex="-1">Poll Interval (ms) <a class="header-anchor" href="#poll-interval-ms" aria-label="Permalink to “Poll Interval (ms)”">​</a></h3><p>The interval in milliseconds between successive checks.</p><ul><li><strong>Default:</strong> <code>200</code> ms</li></ul><h3 id="should-we-use-timeout" tabindex="-1">Should we use timeout? <a class="header-anchor" href="#should-we-use-timeout" aria-label="Permalink to “Should we use timeout?”">​</a></h3><p>A toggle option to define a maximum wait time:</p><ul><li><strong>Toggle OFF</strong> - Keeps waiting and polling in the background until the condition is met.</li><li><strong>Toggle ON</strong> - Enforces a maximum wait duration defined in the <strong>Timeout (ms)</strong> input. If the timeout duration expires before the condition is satisfied, a timeout warning is logged and execution halts gracefully.</li></ul><h3 id="action-on-success" tabindex="-1">Action on Success <a class="header-anchor" href="#action-on-success" aria-label="Permalink to “Action on Success”">​</a></h3><p>Specify the action to execute once the monitored condition is satisfied:</p><ul><li><strong>Click monitored element</strong> - Triggers a click event on the element being monitored.</li><li><strong>Click another element</strong> - Triggers a click event on a different target element specified by a selector.</li></ul><h3 id="another-element-selector" tabindex="-1">Another Element Selector <a class="header-anchor" href="#another-element-selector" aria-label="Permalink to “Another Element Selector”">​</a></h3><p>Visible when <strong>Action on Success</strong> is set to <strong>Click another element</strong>.</p><ul><li>Provide the CSS selector for the target element to click once the condition is met.</li><li>Supports pre-defined variables in selector queries.</li></ul><h3 id="wait-before-executing-action" tabindex="-1">Wait before executing action? <a class="header-anchor" href="#wait-before-executing-action" aria-label="Permalink to “Wait before executing action?”">​</a></h3><p>A toggle option to introduce a delay between the moment the condition is satisfied and the execution of the success action.</p><ul><li><strong>Wait Time Before Action (ms)</strong> - Input the delay in milliseconds to wait before triggering the click action.</li></ul><h2 id="field-selector-configuration" tabindex="-1">Field Selector Configuration <a class="header-anchor" href="#field-selector-configuration" aria-label="Permalink to “Field Selector Configuration”">​</a></h2><p>Use the field&#39;s selector settings to specify the element to monitor:</p><ul><li><strong>Field Selector Query</strong> - CSS Selector, ID, or XPath of the element to watch.</li></ul><h2 id="best-practices-tips" tabindex="-1">Best Practices &amp; Tips <a class="header-anchor" href="#best-practices-tips" aria-label="Permalink to “Best Practices &amp; Tips”">​</a></h2><ul><li><strong>Modals &amp; Dialogs:</strong> When waiting for an animation or popup modal to appear, set the condition to <strong>Element becomes visible</strong> and use <strong>Wait before executing action</strong> (e.g., 500ms) to ensure smooth transitions before clicking buttons.</li><li><strong>Timeouts:</strong> Enable timeout on critical steps to prevent automation from getting permanently stuck if an element never changes state.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field-settings.html">Field Settings</a> - Configure advanced field options</li><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field-types.html">Field Types</a> - Explore other field types</li><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template</a> - Prepare Excel (.xlsx) templates</li><li><img src="/svg/browser.svg" class="doc-icon"> <a href="/documentation/form/form.html">Form Configuration</a> - Set up complete form automation</li></ul>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};